using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1StoryGroundCheck {public static object Run(){string root=Path.GetFullPath(Application.dataPath+"/../../..");var rows=JArray.Parse(File.ReadAllText(root+"/SourceAssets/F1_EnvironmentalStory/roots.json")).Select(q=>{var p=q["world"].Values<float>().ToArray();bool hit=Physics.Raycast(new Vector3(p[0],.8f,p[2]),Vector3.down,out var h,3,~0,QueryTriggerInteraction.Ignore);return new{wall=(string)q["wall"],x=p[0],z=p[2],rootY=p[1],ground=hit?h.point.y:-999,offset=hit?p[1]-h.point.y:999};}).ToArray();File.WriteAllText(root+"/Docs/Review/2026-11-13_1F_EnvironmentalStory/root_ground.json",JsonConvert.SerializeObject(rows,Formatting.Indented));return new{roots=rows.Length,minOffset=rows.Min(q=>q.offset),maxOffset=rows.Max(q=>q.offset),outsideTolerance=rows.Count(q=>Mathf.Abs(q.offset)>.05f)};}}
